using Servicio.RetazoMarket.Business.DTOs.Favorito;using Servicio.RetazoMarket.Business.Exceptions;using Servicio.RetazoMarket.Business.Interfaces;using Servicio.RetazoMarket.Business.Mappers;using Servicio.RetazoMarket.Business.Validators;using Servicio.RetazoMarket.DataManagment.Interfaces;using Servicio.RetazoMarket.DataManagment.Models;using Servicio.RetazoMarket.DataManagment.Models.Common;
namespace Servicio.RetazoMarket.Business.Services;public class FavoritoService:IFavoritoService {private readonly IFavoritoDataService _data;private readonly IClienteDataService _clientes;private readonly IProductoDataService _productos;public FavoritoService(IFavoritoDataService data,IClienteDataService clientes,IProductoDataService productos)=>(_data,_clientes,_productos)=(data,clientes,productos);public async Task<FavoritoResponse?> ObtenerAsync(int c,int p,int actor,CancellationToken ct=default){Autorizar(c,actor);var m=await _data.ObtenerAsync(c,p,ct);return m is null?null:FavoritoBusinessMapper.ToResponse(m);}public async Task<IReadOnlyList<FavoritoResponse>> ObtenerPorClienteAsync(int c,int actor,CancellationToken ct=default){Autorizar(c,actor);return (await _data.ObtenerPorClienteAsync(c,ct)).Select(FavoritoBusinessMapper.ToResponse).ToList();}public async Task<DataPagedResult<FavoritoResponse>> BuscarAsync(FavoritoFiltroRequest f,int actor,CancellationToken ct=default){var e=FavoritoValidator.ValidarFiltro(f);if(e.Any())throw new ValidationException("Filtro inválido.",e);Autorizar(f.id_cliente,actor);var r=await _data.BuscarPorClienteAsync(new FavoritoFiltroDataModel{id_cliente=f.id_cliente,nombre_producto=f.nombre_producto?.Trim(),id_linea=f.id_linea,estado_producto=f.estado_producto?.Trim().ToUpperInvariant(),PageNumber=f.page_number,PageSize=f.page_size},ct);return new(){Items=r.Items.Select(FavoritoBusinessMapper.ToResponse).ToList(),PageNumber=r.PageNumber,PageSize=r.PageSize,TotalRecords=r.TotalRecords};}public async Task<FavoritoResponse> AgregarAsync(AgregarFavoritoRequest r,int actor,CancellationToken ct=default){var e=FavoritoValidator.Validar(r);if(e.Any())throw new ValidationException("Solicitud inválida.",e);Autorizar(r.id_cliente,actor);var cliente=await _clientes.ObtenerPorIdAsync(r.id_cliente,ct);if(cliente is null||cliente.cli_estado!="ACT")throw new ValidationException("El cliente no existe o está inactivo.");if(await _productos.ObtenerPorIdAsync(r.id_producto,ct) is null)throw new ValidationException("El producto no existe.");if(await _data.ExisteAsync(r.id_cliente,r.id_producto,ct))throw new ValidationException("El producto ya está en favoritos.");await _data.CrearAsync(FavoritoBusinessMapper.ToDataModel(r),ct);var creado=await _data.ObtenerAsync(r.id_cliente,r.id_producto,ct)??throw new BusinessException("No fue posible recuperar el favorito creado.");return FavoritoBusinessMapper.ToResponse(creado);}public async Task<bool> QuitarAsync(int c,int p,int actor,CancellationToken ct=default){Autorizar(c,actor);return await _data.EliminarAsync(c,p,ct);}private static void Autorizar(int cliente,int actor){if(cliente<=0||actor<=0||cliente!=actor)throw new UnauthorizedBusinessException("No está autorizado para operar sobre los favoritos de otro cliente.");}}
